 static final class Row {String id;boolean visible,pinned;Row(String key,boolean on,boolean pin){id=key;visible=on;pinned=pin;}}
 static final List<String> NEW_ROWS=Arrays.asList("because-2","picked","fav-like","genre-popular","genre-top");
 static JSONArray migrate(JSONArray saved){
  if(saved==null||saved.length()==0)return saved;
  List<JSONObject> entries=new ArrayList<>(DataStore.objects(DataStore.copyArray(saved)));boolean modern=false;for(JSONObject e:entries)if(NEW_ROWS.contains(e.optString("id")))modern=true;if(modern)return saved;
  JSONObject ready=null;for(Iterator<JSONObject> it=entries.iterator();it.hasNext();){JSONObject e=it.next();if(e.optString("id").equals("ready")){ready=e;it.remove();break;}}
  if(ready!=null){int at=entries.size();for(int n=0;n<entries.size();n++)if(entries.get(n).optString("id").equals("list")){at=n+1;break;}entries.add(at,ready);}
  int at=entries.size();for(int n=0;n<entries.size();n++)if(entries.get(n).optString("id").equals("because")){at=n+1;break;}
  for(String id:NEW_ROWS){JSONObject e=new JSONObject();DataStore.put(e,"id",id);DataStore.put(e,"visible",true);entries.add(at++,e);}JSONArray result=new JSONArray();for(JSONObject e:entries)result.put(e);return result;
 }
 static List<Row> resolve(JSONArray saved,Collection<String> available){Set<String> known=new LinkedHashSet<>(DEFAULTS);known.addAll(available);List<Row> rows=new ArrayList<>();Set<String> seen=new HashSet<>();rows.add(new Row("continue",true,false));seen.add("continue");for(JSONObject value:DataStore.objects(saved)){String id=value.optString("id");if(known.contains(id)&&seen.add(id))rows.add(new Row(id,value.optBoolean("visible",true),value.optBoolean("pinned")));}for(String id:known)if(seen.add(id))rows.add(new Row(id,DEFAULTS.contains(id),false));return rows;}
 static JSONArray encode(List<Row> rows){JSONArray saved=new JSONArray();for(Row row:rows){JSONObject value=new JSONObject();DataStore.put(value,"id",row.id);DataStore.put(value,"visible",row.id.equals("continue")||row.visible);DataStore.put(value,"pinned",row.pinned);saved.put(value);}return saved;}
