  builders.put("queue",()->{List<JSONObject> picks=new ArrayList<>();List<View> cards=new ArrayList<>();for(Object value:jsonValues(a.data.playQueue())){JSONObject i=a.data.item(String.valueOf(value));if(i==null)continue;List<JSONObject> g=a.group(i.optString("group"));if(g!=null){cards.add(a.ui.posterCard(g));picks.add(i);}}Runnable all=()->showPicks(Loc.t("Your play queue"),picks);endTile(cards,all);a.ui.rail(a.body,"Your play queue","",cards,all);});
  for(String id:NEW_ROWS)names.put(id,Loc.t(id.equals("because-2")?"Because you watched…":id.equals("picked")?"Picked for you":id.equals("fav-like")?"More like your favourites":id.equals("genre-top")?"Top rated in your top genre":"Popular in your top genre"));
  for(int n=0;n<2;n++){final int index=n;builders.put(n==0?"because":"because-2",()->{if(watched.size()<=index)return;JSONObject seed=watched.get(index).get(0);recommendation(Loc.f("Because you watched %s",seed.optString("title")),Loc.f("More %s to discover",topGenre(List.of(List.of(seed)))),genre(seed),groups,false,index==0?"because":"because-2");});}
  List<List<JSONObject>> favorites=new ArrayList<>();for(List<JSONObject> g:groups)if(a.data.liked(g.get(0).optString("group"))||jsonValues(a.data.favorites()).contains(g.get(0).optString("group")))favorites.add(g);
  Set<String> tastes=new LinkedHashSet<>();for(List<JSONObject> g:favorites)tastes.addAll(genre(g.get(0)));for(List<JSONObject> g:groups)if(g.stream().anyMatch(i->DataStore.rating10(i)>=8))tastes.addAll(genre(g.get(0)));String top=topGenre(watched);if(!top.isEmpty())tastes.add(top);
  builders.put("picked",()->recommendation("Picked for you","Inspired by your favourites, ratings and viewing",tastes,groups,false));
