  builders.put("genre-popular",()->{if(!top.isEmpty())recommendation(Loc.f("Popular in %s",Loc.t(top)),"Popular in your top genre",Set.of(top),groups,false);});
  builders.put("genre-top",()->{if(!top.isEmpty())recommendation(Loc.f("Top rated in %s",Loc.t(top)),"Top rated in your top genre",Set.of(top),groups,true);});
  builders.put("genres",()->{int n=0;for(String genre:genres){if(n++>=3)break;genreRow(genre,groups);}});for(String genre:genres){String id="genre:"+genre;names.put(id,Loc.t(genre));builders.put(id,()->genreRow(genre,groups));}
  builders.put("collections",()->{int n=0;for(String collection:collections){if(n++>=3)break;collectionRow(collection,groups);}});for(String collection:collections){String id="collection:"+collection;names.put(id,collection);builders.put(id,()->collectionRow(collection,groups));}
  for(Row row:resolve(a.data.prefs().optJSONArray("homeLayout"),builders.keySet()))if(row.visible&&builders.containsKey(row.id))builders.get(row.id).run();TextView edit=a.ui.chip("Edit Home",this::edit,false);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-2,-2);ep.setMargins(0,a.dp(30),0,a.dp(20));a.body.addView(edit,ep);PhoneJustWatched.accessible(a.body);
