 static String topGenre(List<List<JSONObject>> groups){Map<String,Integer> counts=new LinkedHashMap<>();for(List<JSONObject> g:groups)for(String genre:genre(g.get(0)))counts.merge(genre,1,Integer::sum);String best="";int max=0;for(Map.Entry<String,Integer> e:counts.entrySet())if(e.getValue()>max){best=e.getKey();max=e.getValue();}return best;}
 static boolean excluded(List<JSONObject> group){return group.stream().anyMatch(i->DataStore.watched(i)||i.optBoolean("hidden")||i.optString("status").equals("Dropped"));}
 static String identity(JSONObject i){String imdb=i.optString("imdb");return imdb.isEmpty()?i.optString("id",i.optString("group")):imdb;}
 static List<JSONObject> fillRecommendations(List<List<JSONObject>> groups,Set<String> genres,JSONArray catalog,int limit){return fillRecommendations(groups,genres,catalog,limit,true);}
 static List<JSONObject> fillRecommendations(List<List<JSONObject>> groups,Set<String> genres,JSONArray catalog,int limit,boolean libraryFirst){
  List<JSONObject> picks=new ArrayList<>();Set<String> blocked=new HashSet<>(),seen=new HashSet<>();for(List<JSONObject> g:groups)if(excluded(g)){blocked.add(identity(g.get(0)));blocked.add(g.get(0).optString("group"));}
  for(List<JSONObject> g:groups){JSONObject i=g.get(0);if(libraryFirst&&!excluded(g)&&!blocked.contains(identity(i))&&!Collections.disjoint(genres,genre(i))&&seen.add(identity(i))&&picks.size()<limit)picks.add(i);}
  for(JSONObject i:DataStore.objects(catalog))if(!blocked.contains(identity(i))&&!blocked.contains(i.optString("group"))&&!i.optBoolean("hidden")&&!i.optString("status").equals("Dropped")&&!DataStore.watched(i)&&seen.add(identity(i))&&picks.size()<limit)picks.add(i);return picks;
 }
 final Map<String,JSONArray> catalogs=new HashMap<>();final Set<String> catalogPending=new HashSet<>();final Map<String,List<Runnable>> catalogReady=new HashMap<>();
 final java.util.concurrent.ExecutorService catalogWork=java.util.concurrent.Executors.newFixedThreadPool(2);
 void close(){catalogWork.shutdownNow();catalogReady.clear();}

 void recommendation(String title,String reason,Set<String> genres,List<List<JSONObject>> groups,boolean topRated){recommendation(title,reason,genres,groups,topRated,"");}
 void recommendation(String title,String reason,Set<String> genres,List<List<JSONObject>> groups,boolean topRated,String row){
  if(genres.isEmpty())return;LinearLayout slot=a.column();a.body.addView(slot);String genre=genres.iterator().next(),key=genre+":"+topRated;JSONArray cached=catalogs.get(key);fillRecommendation(slot,title,reason,genres,groups,cached,row);
  if(cached!=null)return;long revision=a.renderRevision;catalogReady.computeIfAbsent(key,k->new ArrayList<>()).add(()->{if(!a.isDestroyed()&&revision==a.renderRevision&&slot.isAttachedToWindow()){slot.removeAllViews();fillRecommendation(slot,title,reason,genres,a.groups(),catalogs.get(key),row);}});if(!catalogPending.add(key))return;
  catalogWork.execute(()->{JSONArray found=null;try{found=new DiscoveryClient(a.data.context).genreCatalog(genre,topRated);}catch(Exception ignored){}final JSONArray result=found;a.runOnUiThread(()->{catalogPending.remove(key);if(result!=null)catalogs.put(key,result);List<Runnable> ready=catalogReady.remove(key);if(ready!=null&&result!=null)for(Runnable update:ready)update.run();});});
 }
 void fillRecommendation(LinearLayout slot,String title,String reason,Set<String> genres,List<List<JSONObject>> groups,JSONArray catalog,String row){List<View> cards=new ArrayList<>();boolean genreOnly=reason.equals("Popular in your top genre")||reason.equals("Top rated in your top genre");List<JSONObject> found=new ArrayList<>(fillRecommendations(groups,genres,catalog,row.equals("because-2")?40:20,!genreOnly));if(row.equals("because-2"))found.removeIf(i->becauseFirst.contains(identity(i)));else if(row.equals("because")){becauseFirst.clear();for(JSONObject i:found)becauseFirst.add(identity(i));}final List<JSONObject> picks=found.size()>20?new ArrayList<>(found.subList(0,20)):found;for(JSONObject item:picks){View card;List<JSONObject> g=a.group(item.optString("group"));if(title.equals("Picked for you")&&cards.isEmpty())card=spotlight(item,g);else if(g!=null)card=a.ui.posterCard(g);else card=catalogCard(item);if(card instanceof LinearLayout){TextView why=a.text(reason,11,MainActivity.GOLD);why.setMaxLines(2);((LinearLayout)card).addView(why);}cards.add(card);}Runnable all=()->showPicks(title,picks);endTile(cards,all);a.ui.rail(slot,title,Loc.t(reason),cards,all);PhoneJustWatched.accessible(slot);}
 View spotlight(JSONObject item,List<JSONObject> group){JSONObject art=group==null?TvRows.art(item):item;LinearLayout card=a.column();LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(a.dp(300),-2);cp.setMargins(0,0,a.dp(14),0);card.setLayoutParams(cp);card.addView(a.ui.art(art,false,-1,a.dp(168)));TextView title=a.text(art.optString("title"),20,MainActivity.WHITE);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setMaxLines(2);card.addView(title);card.setContentDescription(art.optString("title"));card.setFocusable(true);card.setOnClickListener(v->{if(group!=null)a.open(item,card);else DiscoverSheet.show(a,item,card);});Motion.card(card);return card;}

 View catalogCard(JSONObject title){JSONObject art=TvRows.art(title);LinearLayout card=a.column();LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(a.dp(136),-2);cp.setMargins(0,0,a.dp(12),0);card.setLayoutParams(cp);card.addView(a.ui.art(art,true,-1,a.dp(196)));TextView label=a.text(art.optString("title"),13,MainActivity.WHITE);label.setMaxLines(2);card.addView(label);card.setContentDescription(art.optString("title"));card.setFocusable(true);card.setOnClickListener(v->DiscoverSheet.show(a,title,card));Motion.card(card);return card;}
