 View continueCard(NoirUi.Next next){LinearLayout card=(LinearLayout)a.ui.continueCard(next);JSONObject i=next.item,p=i.optJSONObject("progress");double duration=p==null?i.optDouble("duration"):p.optDouble("duration",i.optDouble("duration"));if(MainActivity.position(i)>0&&!MainActivity.completed(i)&&duration>0){for(int n=2;n<card.getChildCount();n++)if(card.getChildAt(n) instanceof TextView){((TextView)card.getChildAt(n)).setText((i.optBoolean("movie")?"":MainActivity.episode(i)+" · ")+Loc.minutesLeft((int)Math.max(0,(duration-MainActivity.position(i))/60)));break;}}return card;}

 long smartRevision=-1;Map<String,List<SmartLists.Pick>> cachedSmartRows;Map<String,JSONObject> smartCredits=new HashMap<>();long creditsStamp=Long.MIN_VALUE;boolean creditsLoading=false;
 void warmCredits(List<List<JSONObject>> groups){java.io.File folder=new java.io.File(a.data.context.getCacheDir(),"credits");long stamp=folder.lastModified();if(creditsLoading||creditsStamp==stamp)return;creditsLoading=true;List<JSONObject> firsts=new ArrayList<>();for(List<JSONObject> g:groups)firsts.add(g.get(0));a.data.images.execute(()->{Map<String,JSONObject> cache=new HashMap<>();for(JSONObject first:firsts){JSONObject meta=PhoneCatchUp.cachedMeta(a.data,first);if(meta.length()>0)cache.put(first.optString("group"),meta);}a.runOnUiThread(()->{creditsLoading=false;creditsStamp=stamp;smartCredits=cache;if(!a.isDestroyed())a.render();});});}
 Map<String,List<SmartLists.Pick>> smartRows(List<List<JSONObject>> groups){if(smartRevision==a.renderRevision&&cachedSmartRows!=null)return cachedSmartRows;warmCredits(groups);JSONObject settings=a.browsingSettings();List<SmartLists.Title> titles=new ArrayList<>();long now=System.currentTimeMillis();boolean stream=PhoneStream.available(a),pc=a.data.online&&a.data.paired();for(List<JSONObject> g:groups){JSONObject meta=smartCredits.get(g.get(0).optString("group"));titles.add(SmartLists.read(g,settings,meta==null?Collections.emptyList():PhoneCatchUp.directors(meta),i->stream&&SmartLists.streamReady(a.data.profileId,i.optString("id"),now)||!a.data.localFile(i.optString("id")).isEmpty()||pc&&i.optBoolean("available")));}smartRevision=a.renderRevision;cachedSmartRows=SmartLists.build(titles,now,Loc.arabic);return cachedSmartRows;}
 Set<String> smartKeys(List<List<JSONObject>> groups){if(smartFilter.equals("All"))return null;Set<String> keys=new HashSet<>();for(SmartLists.Pick pick:smartRows(groups).get(smartFilter))keys.add(pick.key);return keys;}
